// ---------------------------------------------------------------------------
// Animated counter hook
// ---------------------------------------------------------------------------
function useAnimatedCounter(target: number, duration = 2000, delay = 0) {
  const [value, setValue] = useState(0);
  const ref = useRef<HTMLSpanElement>(null);
  const inView = useInView(ref, { once: true, margin: "-50px" });

  useEffect(() => {
    if (!inView) return;
    const timeout = setTimeout(() => {
      const startTime = performance.now();
      const step = (now: number) => {
        const elapsed = now - startTime;
        const progress = Math.min(elapsed / duration, 1);
        const eased = 1 - Math.pow(1 - progress, 3); // ease-out cubic
        setValue(Math.round(eased * target));
        if (progress < 1) requestAnimationFrame(step);
      };
      requestAnimationFrame(step);
    }, delay);
    return () => clearTimeout(timeout);
  }, [inView, target, duration, delay]);

  return { ref, value };
}

// ---------------------------------------------------------------------------
// Stat card
// ---------------------------------------------------------------------------
interface StatCardProps {
  prefix?: string;
  value: number;
  suffix?: string;
  label: string;
  delay?: number;
}

function StatCard({ prefix, value, suffix, label, delay = 0 }: StatCardProps) {
  const { ref, value: animated } = useAnimatedCounter(value, 1800, delay);

  const formatted = value >= 1000
    ? animated.toLocaleString("fr-CH")
    : animated.toString();

  return (
    <motion.div
      initial={{ opacity: 0, y: 24 }}
      animate={{ opacity: 1, y: 0 }}
      transition={{ delay: 0.8 + delay / 1000, duration: 0.5, ease: "easeOut" }}
      className="flex flex-col items-center gap-1 px-5 py-4 rounded-2xl bg-white/5 border border-white/10 backdrop-blur-sm min-w-[130px]"
    >
      <span ref={ref} className="text-2xl font-bold text-white tabular-nums">
        {prefix}{formatted}{suffix}
      </span>
      <span className="text-xs text-blue-300/80 text-center leading-tight">{label}</span>
    </motion.div>
  );
}

